#!/usr/bin/env python3
"""sun: an operation log for humans + agents on top of git.

Every change is a commit attributed as <user>/<source>: <user>/local for
changes on <user>'s machine not made by a tracked agent, or
<user>/agent:<harness>/<session>. Live: PreToolUse commits dirty state as
local, PostToolUse commits the pre->post diff as the agent's, Stop squashes
the turn into one commit (per-call commits stay under refs/sun/ops) and
appends the turn's transcript chunk to refs/sun/sessions/<user>/<id>.
`sun init` imports the folder's existing sessions and backfills attribution
over existing commits (method: transcript_backfill). Storage: events in
.git/sun/events.jsonl (a per-machine cache), mirrored to refs/sun/log/<user>
(one writer each, merged by timestamp at read); transcripts are git objects
under refs/sun/sessions/*, never in the worktree, pushed/fetched via the
refspec + fail-soft pre-push hook `sun init` installs. Concurrency:
.git/sun/lock (flock) serializes every command and hook, like git's index.lock.
"""
import argparse, difflib, fcntl, glob, hashlib, json, os, re, subprocess, sys
import time, uuid, zlib
from datetime import datetime

EDIT_TOOLS = {"Edit", "Write", "MultiEdit", "NotebookEdit"}
CLAUDE_LINE = ("Past sessions for this repo, yours and other team members', are "
               "in .git/sun/sessions/ (same layout as ~/.claude/projects/, with "
               "a sessions-index.json). Look there instead of ~/.claude/projects/.")

def projects():
    return os.environ.get("SUN_PROJECTS", os.path.expanduser("~/.claude/projects"))

# ---------------------------------------------------------------- git plumbing

def sh(*args, input=None, check=True, env=None):
    p = subprocess.run(args, capture_output=True, text=True, input=input, env=env)
    if check and p.returncode:
        sys.exit(f"sun: `{' '.join(args)}` failed: {p.stderr.strip()}")
    return p.stdout

def git(*args, **kw):
    return sh("git", *args, **kw)

def root():
    return git("rev-parse", "--show-toplevel").strip()

def head():
    return git("rev-parse", "HEAD").strip()

def changed_files():
    files = []
    for line in git("-c", "core.quotepath=false", "status", "--porcelain",
                    "-uall").splitlines():
        f = line[3:].split(" -> ")[-1]
        if f.startswith('"'):  # control chars still come quoted/escaped
            f = (f[1:-1].encode("latin1").decode("unicode_escape")
                 .encode("latin1").decode("utf-8"))
        files.append(f)
    return files

def commit_files(files, message, author):
    git("add", "-A", "--", *files, check=False)  # pathspec may match nothing
    git("-c", "commit.gpgsign=false", "commit", "-q", "--no-verify",
        "--allow-empty", "--author", f"{author} <sun@sun>", "-m", message)
    return head()

def patches(pre, post, files):
    return {f: git("diff", pre, post, "--", f) for f in files}

def patch_id(c):
    out = git("patch-id", "--stable", check=False,
              input=git("show", "--format=", c, check=False)).split()
    return out[0] if out else None

def blob(data):  # loose object via hashlib/zlib: no subprocess per chunk
    b = data.encode() if isinstance(data, str) else data
    hdr, = [b"blob %d\x00" % len(b)]
    sha = hashlib.sha1(hdr + b).hexdigest()
    p = os.path.join(root(), ".git", "objects", sha[:2], sha[2:])
    if not os.path.exists(p):
        os.makedirs(os.path.dirname(p), exist_ok=True)
        open(p, "wb").write(zlib.compress(hdr + b))
    return sha

def refs(prefix):  # [(refname, sha)]
    out = git("for-each-ref", "--format=%(refname)\t%(objectname)", prefix,
              check=False)
    return [l.split("\t") for l in out.splitlines()]

# ------------------------------------------------------------- .git/sun state

def sun_dir(must=True):
    d = os.path.join(root(), ".git", "sun")
    if must and not os.path.isdir(d):
        sys.exit("sun: not initialized here (run `sun init`)")
    return d

def jread(path, default):
    try:
        with open(path) as f:
            return json.load(f)
    except (OSError, ValueError):
        return default

def jwrite(path, obj):
    with open(path, "w") as f:
        json.dump(obj, f, indent=1)

def state(name, default):
    return jread(os.path.join(sun_dir(), name), default)

def save_state(name, obj):
    jwrite(os.path.join(sun_dir(), name), obj)

def parse_events(text):
    out = []
    for l in text.splitlines():
        try:
            out.append(json.loads(l))
        except ValueError:
            pass  # skip torn/corrupt lines rather than brick every command
    return out

def events():  # own cache first (file order), then teammates' logs; stable sort
    try:
        evs = parse_events(open(os.path.join(sun_dir(), "events.jsonl")).read())
    except OSError:
        evs = []
    for ref, sha in refs("refs/sun/log/"):
        if ref.split("/")[-1] != user():
            evs += parse_events(git("cat-file", "blob", sha, check=False))
    return sorted(evs, key=lambda e: e.get("timestamp", ""))

def lock():
    lk = open(os.path.join(sun_dir(False), "lock"), "a")
    fcntl.flock(lk, fcntl.LOCK_EX)
    return lk  # held until process exit

def mirror_log():  # one writer per user: refs/sun/log/<user> mirrors the cache
    p = os.path.join(sun_dir(), "events.jsonl")
    if os.path.exists(p):
        git("update-ref", f"refs/sun/log/{user()}", blob(open(p).read()))

def record(mirror=True, **ev):
    ev = {"id": uuid.uuid4().hex[:8],
          "timestamp": time.strftime("%Y-%m-%dT%H:%M:%S%z"), **ev}
    with open(os.path.join(sun_dir(), "events.jsonl"), "a") as f:
        f.write(json.dumps(ev) + "\n")
    if mirror:
        mirror_log()
    return ev

def store_chunks(sid, files, u=None):
    """Add {path: text} blobs into the refs/sun/sessions/<u>/<sid> tree."""
    if not files:
        return
    ref = f"refs/sun/sessions/{u or user()}/{sid}"
    ix = os.path.join(sun_dir(), "tmpindex")
    env = {**os.environ, "GIT_INDEX_FILE": ix}
    if os.path.exists(ix):
        os.remove(ix)
    if not subprocess.run(["git", "rev-parse", "-q", "--verify", ref],
                          capture_output=True).returncode:
        git("read-tree", ref, env=env)
    git("update-index", "--index-info", env=env, input="".join(
        f"100644 blob {blob(c)}\t{p}\n" for p, c in files.items()))
    git("update-ref", ref, git("commit-tree", git("write-tree", env=env).strip(),
                               "-m", sid).strip())

# ---------------------------------------------------------------- attribution

_u = {}
def user():  # the git user on whose machine the change happened; owns events
    if "u" not in _u:
        n = git("config", "user.name", check=False).strip() \
            or os.environ.get("USER", "unknown")
        _u["u"] = n.replace(" ", "-").lower()
    return _u["u"]

def local(u=None):
    return f"{u or user()}/local"

def agent(sid):
    return f"{user()}/agent:claude/{sid[:8]}"

call_key = lambda sid, payload: f"{sid}/{payload.get('tool_use_id') or ''}"

def char_edits(patch):
    """Character-level edit ranges for paired -/+ lines of a unified patch."""
    edits, old_ln, new_ln, minus = [], 0, 0, []
    for line in patch.splitlines():
        if line.startswith("@@"):
            nums = line.split("@@")[1].split()[:2]
            if len(nums) < 2:
                break
            old_ln, new_ln = (int(n.lstrip("-+").split(",")[0]) for n in nums)
            minus = []
        elif line.startswith("-") and not line.startswith("---"):
            minus.append((old_ln, line[1:]))
            old_ln += 1
        elif line.startswith("+") and not line.startswith("+++"):
            new = line[1:]
            if minus:
                oln, old = minus.pop(0)
                for tag, a, b, c, d in difflib.SequenceMatcher(
                        None, old, new).get_opcodes():
                    if tag != "equal":
                        edits.append({"old_line": oln, "new_line": new_ln,
                                      "old_range": [a, b], "new_range": [c, d],
                                      "old_text": old[a:b], "new_text": new[c:d]})
            new_ln += 1
        elif not line.startswith("\\") and not line.startswith("diff "):
            old_ln, new_ln, minus = old_ln + 1, new_ln + 1, []
    return edits

def sync(exclude=frozenset()):
    """Commit changes not claimed by an in-flight agent tool call as local."""
    active = state("active.json", {})
    exclude = set(exclude) | {f for s in active.values() for f in s["files"]}
    files = [f for f in changed_files() if f not in exclude]
    if not files:
        return None
    pre, actor = head(), local()
    c = commit_files(files, f"sun: {actor} edits", actor)
    p = patches(pre, c, files)
    return record(type="edit", actor=actor, commit=c, patch_id=patch_id(c),
                  edits=[{"file": f, "patch": p[f], "char_edits": char_edits(p[f]),
                          "attribution": {"method": "hook"}} for f in files])

def maybe_sync():
    if not state("active.json", {}):  # skip while a tool call is in flight
        sync()

# ------------------------------------------------------------ hook entrypoint

def tool_file(inp):
    return inp.get("file_path") or inp.get("notebook_path")

def rel_to_root(path):
    return os.path.relpath(os.path.realpath(path), root())

def finish_call(sid, active, payload):
    """PostToolUse: the pre-tool -> post-tool diff is this agent's tool call."""
    st = (active.pop(call_key(sid, payload), None)  # or an id-less claim
          or active.pop(call_key(sid, {}), None) or {"files": []})
    save_state("active.json", active)
    others = {f for s in active.values() for f in s["files"]}
    files = [f for f in changed_files() if f not in others]
    if not files:
        return
    tool, inp = payload.get("tool_name", "?"), payload.get("tool_input") or {}
    call = {"id": payload.get("tool_use_id"), "tool": tool,
            "input": {"file": rel_to_root(tool_file(inp))} if tool_file(inp) else inp}
    claimed = set(st["files"]) | ({call["input"]["file"]} if tool_file(inp) else set())
    # an Edit/Write can only touch its own file: anything else in the diff is a
    # concurrent local edit (overlay); for other tools the whole diff is agent
    a_files = [f for f in files if f in claimed] if tool in EDIT_TOOLS else files
    h_files = [f for f in files if f not in a_files]
    actor, pre = agent(sid), head()
    turn = state("turns.json", {}).get(sid, {}).get("n", 0)
    c = commit_files(files, f"sun: {actor} {tool}" if a_files
                     else f"sun: {local()} edits", actor if a_files else local())
    p = patches(pre, c, files)
    if a_files:
        git("update-ref", f"refs/sun/ops/{c}", c)  # survives squash + git gc
        record(type="edit", actor=actor, turn=f"turn{turn}", commit=c,
               patch_id=patch_id(c), tool_calls=[call],
               edits=[{"file": f, "patch": p[f], "tool_call_id": call["id"],
                       "attribution": {"method": "hook"}} for f in a_files])
    if h_files:
        record(type="edit", actor=local(), commit=c,
               edits=[{"file": f, "patch": p[f], "char_edits": char_edits(p[f]),
                       "attribution": {"method": "hook"}} for f in h_files])

def squash_turn(sid):
    """Stop: squash this turn's tool-call commits into one commit per turn.
    Skipped when a foreign commit landed mid-turn; per-call commits stay."""
    t = state("turns.json", {}).get(sid)
    if not t:
        return
    start, actor = t["start"], agent(sid)
    if subprocess.run(["git", "merge-base", "--is-ancestor", start, "HEAD"],
                      capture_output=True).returncode:
        return
    rng = git("rev-list", f"{start}..HEAD").split()
    ops = [e for e in events() if e.get("commit") in rng]
    mine = [e for e in ops if e["actor"] == actor and "squashes" not in e]
    if not rng or set(rng) - {e["commit"] for e in mine}:
        return
    # commit-tree + update-ref never touch the worktree/index: local edits made
    # after the last tool call stay dirty instead of folding into the turn
    c = git("-c", f"user.name={actor}", "-c", "user.email=sun@sun", "commit-tree",
            git("rev-parse", "HEAD^{tree}").strip(), "-p", start,
            "-m", f"sun: {actor} turn {t['n']} ({len(rng)} tool calls)").strip()
    git("update-ref", "HEAD", c, head())
    files = git("diff", "--name-only", start, c).splitlines()
    p = patches(start, c, files)
    record(type="edit", actor=actor, turn=f"turn{t['n']}", commit=c,
           patch_id=patch_id(c), squashes=[e["id"] for e in mine],
           tool_calls=[tc for e in mine for tc in e["tool_calls"]],
           edits=[{"file": f, "patch": p[f],
                   "attribution": {"method": "squash"}} for f in files])
    for e in ops:  # overlays inside the agent's commits follow the squash
        if e not in mine:
            record(type=e["type"], actor=e["actor"], commit=c, edits=e["edits"],
                   overlay_of=e["id"])

def stop_chunk(sid, payload):
    """Stop: append this turn's transcript slice to the session ref."""
    turns = state("turns.json", {})
    t = turns.get(sid)
    tp = payload.get("transcript_path") or (t or {}).get("transcript", "")
    if not (t and tp and os.path.exists(tp) and cfg_track()):
        return
    with open(tp, errors="replace") as f:
        f.seek(t.get("toffset", 0))
        data = f.read()
    if data:
        store_chunks(sid, {f"turn-{t['n']:04d}.jsonl": data})
    t["toffset"] = os.path.getsize(tp)
    save_state("turns.json", turns)

def cmd_hook(a):
    try:
        payload = json.load(sys.stdin)
    except (ValueError, OSError):
        payload = {}
    if payload.get("cwd"):
        try:
            os.chdir(payload["cwd"])
        except OSError:
            return
    p = subprocess.run(["git", "rev-parse", "--show-toplevel"],
                       capture_output=True, text=True)
    top = p.stdout.strip()
    if p.returncode or not os.path.isdir(os.path.join(top, ".git", "sun")):
        return  # not a sun repo; hooks must never break the harness
    os.chdir(top)
    lk = lock()  # serialize concurrent hooks (parallel sessions/subagents)
    event, sid = payload.get("hook_event_name", ""), payload.get("session_id", "?")
    active = state("active.json", {})
    if event in ("SessionStart", "UserPromptSubmit", "PreToolUse"):
        sync()  # everything dirty before an agent tool runs is <user>/local
    if event == "SessionStart":
        print(f"sun: past sessions for this repo (yours + teammates') are in "
              f".git/sun/sessions/, not ~/.claude/projects; "
              f"{export_sessions()} sessions")
    elif event == "UserPromptSubmit":
        turns, tp = state("turns.json", {}), payload.get("transcript_path", "")
        turns[sid] = {"n": turns.get(sid, {}).get("n", 0) + 1, "start": head(),
                      "transcript": tp,
                      "toffset": os.path.getsize(tp) if os.path.exists(tp) else 0}
        save_state("turns.json", turns)
    elif event == "PreToolUse":  # claim the file BEFORE the write exists
        f = tool_file(payload.get("tool_input") or {})
        active[call_key(sid, payload)] = {"files": [rel_to_root(f)] if f else []}
        save_state("active.json", active)
    elif event == "PostToolUse":
        finish_call(sid, active, payload)
    elif event == "Stop":
        squash_turn(sid)
        stop_chunk(sid, payload)

# ------------------------------------------------------------- session import

def enc(path):
    return re.sub(r"[/.]", "-", path)

def project_dirs():
    wt = [l.split(" ", 1)[1] for l in git("worktree", "list", "--porcelain",
                                          check=False).splitlines()
          if l.startswith("worktree ")]
    names = {enc(p) for r in [root()] + wt for p in (r, os.path.realpath(r))}
    return [d for d in glob.glob(os.path.join(projects(), "*"))
            if os.path.basename(d) in names
            or any(os.path.basename(d).startswith(n + "--claude-worktrees-")
                   for n in names)]

def scan_transcript(path, sid):
    """Turn chunks + edit tool calls [(epoch, sid, tool_id, abspath)]."""
    chunks, cur, calls = [], [], []
    for line in open(path, errors="replace"):
        if ('"type":"user"' in line or '"type": "user"' in line) \
                and "tool_result" not in line and cur:
            chunks.append("".join(cur))
            cur = []
        cur.append(line)
        if '"tool_use"' in line:
            try:
                obj = json.loads(line)
            except ValueError:
                continue
            for b in (obj.get("message") or {}).get("content") or []:
                f = (isinstance(b, dict) and b.get("type") == "tool_use"
                     and b.get("name") in EDIT_TOOLS
                     and tool_file(b.get("input") or {}))
                if f and obj.get("timestamp"):
                    try:
                        t = datetime.fromisoformat(
                            obj["timestamp"].replace("Z", "+00:00")).timestamp()
                        calls.append((t, sid, b.get("id"), f))
                    except ValueError:
                        pass
    if cur:
        chunks.append("".join(cur))
    return chunks, calls

def backfill(index):
    """Attribute pre-existing commits: transcript match or <author>/local."""
    have, att, tot, cs, cur = {e.get("commit") for e in events()}, 0, 0, [], None
    for l in git("log", "--name-only", "--pretty=#%H\t%an\t%at",
                 check=False).splitlines():
        if l.startswith("#"):
            cur = l[1:].split("\t") + [[]]
            cs.append(cur)
        elif l.strip() and cur:
            cur[3].append(l)
    for H, an, at, files in cs:
        if H in have:
            continue
        tot += 1
        m = {f: c for f in files for c in [next(
            (c for c in index.get(f, []) if abs(c[0] - int(at)) < 1800), None)] if c}
        u = an.replace(" ", "-").lower()
        actor = (f"{u}/agent:claude/{next(iter(m.values()))[1][:8]}" if m
                 else local(u))
        record(mirror=False, type="edit", actor=actor, commit=H, edits=[
            {"file": f, "patch": "", "tool_call_id": m[f][2] if f in m else None,
             "attribution": {"method": "transcript_backfill" if f in m
                             else "import"}} for f in files])
        att += bool(m)
    return att, tot

def do_import():
    t0, seen = time.time(), state("imported.json", {})
    index, ns, nsub = {}, 0, 0
    for d in project_dirs():
        for path in glob.glob(os.path.join(d, "**", "*.jsonl"), recursive=True):
            rp = os.path.relpath(path, d).split(os.sep)
            sid, sub = (rp[0], rp[-1][:-6]) if len(rp) > 1 else (rp[0][:-6], None)
            st = os.stat(path)
            if seen.get(path) == [st.st_size, int(st.st_mtime)]:
                continue  # idempotent: only new/changed transcripts
            chunks, calls = scan_transcript(path, sid)
            for t, s, tid, f in calls:
                fr = re.sub(r"^\.claude/worktrees/[^/]+/", "",
                            f.split(root() + "/", 1)[-1].lstrip("/"))
                index.setdefault(fr, []).append((t, s, tid))
            if cfg_track():
                pre = f"subagents/{sub}/" if sub else ""
                store_chunks(sid, {f"{pre}turn-{i:04d}.jsonl": c
                                   for i, c in enumerate(chunks, 1)})
            seen[path] = [st.st_size, int(st.st_mtime)]
            ns, nsub = ns + (not sub), nsub + bool(sub)
    save_state("imported.json", seen)
    att, tot = backfill(index)
    mirror_log()
    return (f"imported {ns} sessions, {nsub} subagents; "
            f"attributed {att}/{tot} commits in {time.time() - t0:.1f}s")

# ----------------------------------------------------------- sessions command

def session_rows():  # (sid, user, ref)
    return [(r.split("/", 4)[4], r.split("/")[3], r)
            for r, _ in refs("refs/sun/sessions/")]

def session_text(ref, sub=None):
    pre = f"subagents/{sub}/" if sub else ""
    names = sorted(n for n in git("ls-tree", "-r", "--name-only", ref).splitlines()
                   if n.startswith(pre) and n.count("/") == pre.count("/"))
    return "".join(git("cat-file", "blob", f"{ref}:{n}") for n in names)

def export_sessions():
    """Mirror session refs to .git/sun/sessions/ in ~/.claude/projects layout."""
    base, idx = os.path.join(sun_dir(), "sessions", enc(root())), []
    os.makedirs(base, exist_ok=True)
    for sid, u, ref in session_rows():
        fp = os.path.join(base, sid + ".jsonl")
        open(fp, "w").write(session_text(ref))
        for s in sorted({n.split("/")[1] for n in
                         git("ls-tree", "-r", "--name-only", ref).splitlines()
                         if n.startswith("subagents/")}):
            sp = os.path.join(base, sid, "subagents")
            os.makedirs(sp, exist_ok=True)
            open(os.path.join(sp, s + ".jsonl"), "w").write(session_text(ref, s))
        idx.append({"id": sid, "user": u, "path": fp,
                    "origin": "local" if u == user() else "team"})
    jwrite(os.path.join(base, "sessions-index.json"), idx)
    return len(idx)

def cmd_sessions(a):
    if a.id == "export":
        return print(f"sun: exported {export_sessions()} sessions "
                     f"to .git/sun/sessions/")
    rows = session_rows()
    if a.id:
        for sid, u, ref in rows:
            if sid.startswith(a.id):
                return print(session_text(ref), end="")
        sys.exit("sun: no such session")
    pat = a.grep or (a.file and re.escape(a.file))
    for sid, u, ref in rows:
        if pat and not re.search(pat, session_text(ref)):
            continue
        print(f"{sid}  {u}  "
              f"{len(git('ls-tree', '--name-only', ref).splitlines())} turns")

def cmd_gc(a):
    cut, n = time.time() - a.older_than * 86400, 0
    for ref, sha in refs("refs/sun/sessions/"):
        if int(git("show", "-s", "--format=%ct", sha).strip()) < cut:
            git("update-ref", "-d", ref)
            n += 1
    print(f"sun: dropped {n} session refs (git gc will prune the objects)")

# -------------------------------------------------------------------- init

def cfg_track():  # ask once (tty only, so never on hook runs); default yes
    cfg = state("config.json", {})
    if "track_sessions" not in cfg:
        cfg["track_sessions"] = (sys.stdin.isatty() is False or input(
            "sun: track sessions in git? [Y/n] ").strip().lower() != "n")
        save_state("config.json", cfg)
    return cfg["track_sessions"]

def install_hooks():
    path = os.path.join(root(), ".claude", "settings.json")
    os.makedirs(os.path.dirname(path), exist_ok=True)
    cfg = jread(path, {})
    if not isinstance(cfg.setdefault("hooks", {}), dict):
        sys.exit("sun: unexpected 'hooks' format in .claude/settings.json")
    for event in ("SessionStart", "UserPromptSubmit", "PreToolUse",
                  "PostToolUse", "Stop"):
        group = cfg["hooks"].setdefault(event, [])
        if not any(h.get("command") == "sun hook"
                   for g in group for h in g.get("hooks", [])):
            group.append({"hooks": [{"type": "command", "command": "sun hook"}]})
    jwrite(path, cfg)
    return "claude (.claude/settings.json)"

def install_push():  # travel: fetch refspec + fail-soft pre-push mirror
    if "origin" in git("remote", check=False).split():
        spec = "+refs/sun/*:refs/sun/*"
        if spec not in git("config", "--get-all", "remote.origin.fetch",
                           check=False):
            git("config", "--add", "remote.origin.fetch", spec)
    hp = os.path.join(root(), ".git", "hooks", "pre-push")
    if not os.path.exists(hp):
        open(hp, "w").write('#!/bin/sh\n# sun: mirror op log + sessions\ngit push'
                            ' --no-verify "$1" "+refs/sun/*:refs/sun/*"'
                            ' >/dev/null 2>&1 || true\n')
        os.chmod(hp, 0o755)

def claude_md(choice):
    p = os.path.join(root(), "CLAUDE.md")
    cur = open(p).read() if os.path.exists(p) else ""
    if CLAUDE_LINE in cur:
        return
    if choice is None and sys.stdin.isatty():
        choice = input("sun: add one line to CLAUDE.md so agents find team "
                       "sessions? [Y/n] ").strip().lower() != "n"
    if choice:
        open(p, "a").write(("\n" if cur and not cur.endswith("\n") else "")
                           + CLAUDE_LINE + "\n")
    else:
        print("sun: run `sun init --claude-md` later to enable "
              "team session sharing")

def cmd_init(a):
    if subprocess.run(["git", "rev-parse", "--git-dir"],
                      capture_output=True).returncode:
        sh("git", "init", "-q")
    os.makedirs(os.path.join(root(), ".git", "sun"), exist_ok=True)
    if "origin" in git("remote", check=False).split():  # fresh clone: fetch refs
        git("fetch", "-q", "origin", "+refs/sun/*:refs/sun/*", check=False)
    p = os.path.join(sun_dir(), "events.jsonl")  # rebuild cache from own ref
    sha = git("rev-parse", "-q", "--verify", f"refs/sun/log/{user()}",
              check=False).strip()
    if sha and not os.path.exists(p):
        open(p, "w").write(git("cat-file", "blob", sha))
    harness = install_hooks()
    install_push()
    if subprocess.run(["git", "rev-parse", "HEAD"],
                      capture_output=True).returncode or changed_files():
        c = commit_files(["."], "sun: initial state", local())
        record(type="init", actor=local(), commit=c, edits=[])
    print(f"sun: initialized {root()} (hooks: {harness}); {do_import()}")
    claude_md(a.claude_md)
    cmd_viz(argparse.Namespace(n=0, output=os.path.join(sun_dir(), "viz.html")))
    print(f"open file://{sun_dir()}/viz.html to see your history")

