# ----------------------------------------------------------------------- main

def main(argv=None):
    ap = argparse.ArgumentParser(prog="sun", description=__doc__)
    sub = ap.add_subparsers(dest="cmd", required=True)
    p = sub.add_parser("init", help="git repo + .git/sun + hooks + session import")
    p.add_argument("--claude-md", dest="claude_md", action="store_true",
                   default=None)
    p.add_argument("--no-claude-md", dest="claude_md", action="store_false")
    sub.add_parser("hook", help="agent-harness hook entrypoint (JSON on stdin)")
    sub.add_parser("sync", help="detect and commit pending local edits")
    sub.add_parser("import", help="re-import sessions + backfill attribution")
    p = sub.add_parser("sessions", help="list/read/export sessions in refs/sun")
    p.add_argument("id", nargs="?")
    p.add_argument("--grep")
    p.add_argument("--file")
    p = sub.add_parser("gc", help="drop session refs older than N days")
    p.add_argument("--older-than", type=int, required=True)
    p = sub.add_parser("log", help="git log with actors, sessions and turns")
    p.add_argument("-n", type=int, default=30)
    p = sub.add_parser("show", help="show operations for a commit")
    p.add_argument("commit")
    p = sub.add_parser("undo", help="undo one operation (default: latest) or commit")
    p.add_argument("--op", nargs="?", const="", default=None, metavar="ID")
    p.add_argument("--commit", nargs="?", const="HEAD", default=None, metavar="HASH")
    p = sub.add_parser("viz", help="write an HTML visualization of the op log")
    p.add_argument("-o", "--output", default=None)
    p.add_argument("-n", type=int, default=0)
    a = ap.parse_args(argv)
    if a.cmd not in ("init", "hook"):  # hook locates its repo from the payload
        os.chdir(root())
        sun_dir()
        a.lock = lock()
    {"init": cmd_init, "hook": cmd_hook, "sync": cmd_sync, "log": cmd_log,
     "show": cmd_show, "undo": cmd_undo, "viz": cmd_viz, "import": cmd_import,
     "sessions": cmd_sessions, "gc": cmd_gc}[a.cmd](a)

if __name__ == "__main__":
    main()
